import{_ as o,l,o as r,c as n,v as t,p as s,x as e,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"分割 fracturing","description":"","frontmatter":{"title":"分割 fracturing","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fracturing.md","filePath":"litho/fracturing.md","lastUpdated":1789023840000}'),h={name:"litho/fracturing.md"};function u(E,a,f,m,_,A){const i=l("Mermaid");return r(),n("div",null,[a[1]||(a[1]=t('<h1 id="分割-fracturing" tabindex="-1">分割 fracturing <a class="header-anchor" href="#分割-fracturing" aria-label="Permalink to &quot;分割 fracturing&quot;">​</a></h1><div class="epigraph"><p>VSB 只认识矩形与少数三角形；分割把多边形收成炮，炮数就是写入日历的分子。</p><footer>—— 对照 VSB 掩模写入与 fracturing 的公开工程讨论</footer></div><p><a href="/litho/mask-data-prep">上一课</a>把作业单与坐标钉死。缺口是多边形还要切成写模机 primitive。本课钉 fracturing。掩模工艺修正如何再挪这些炮，留给[下一课](/litho/mpc）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可变成形束（VSB）一次曝光一个矩形（有时三角形）孔径。任意多边形必须分割成不重叠或允许有限重叠的炮。OPC 碎片越短、助条越碎、拐角越多，炮数涨得比面积快。曲线若先折成微矩形，炮数再乘一截——这正是 <a href="/litho/multibeam-mask-writer">多束写入</a> 要躲开的墙。</p><p>缺口是<strong>切法与炮数</strong>，不是再讲 MDP 校验和。把 fracturing 理解成「显示三角化」，会漏掉：分割要满足最大/最小炮尺寸、纵横比、以及后段 PEC 对炮中心的假设。切得太碎，时间墙；切得太贪心，边出现台阶，mask CD 与放置变差。</p><h3 id="重叠炮不是免费平滑" tabindex="-1">重叠炮不是免费平滑 <a class="header-anchor" href="#重叠炮不是免费平滑" aria-label="Permalink to &quot;重叠炮不是免费平滑&quot;">​</a></h3><p>有些流允许炮重叠并调制剂量，用灰度逼近斜边。这能减少台阶，但重叠区的剂量非线性与 PEC 核纠缠，校准更难。合同若按「炮数」考核产能，重叠策略会被惩罚；若按「边粗糙」考核，又必须重叠。二者要在同一张预算里谈。</p><p><span class="marginnote">多束机把 fracturing 换成栅格化。本课对象是 VSB 炮；后课数据量与写入时间会把两条路径对照，不在这里写某型号的最大炮表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算法通称：先切曼哈顿矩形，剩余斜边用梯形/三角形或小矩形阶梯逼近。目标函数是炮数、最大边误差、以及避免细长炮（充电与库仑效应更差）。与 MRC 的接口：分割不能把合法多边形切成违例的细条——有时要先合并 jog 再切。</p><p>输出是炮列表：位置、长宽、剂量权重。这是写模机的真正输入。die-to-database 的金标准通常仍是分割前多边形；检验到的边与炮台阶之间的差，要有明确公差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>孔径成形有最小尺寸与离散台阶。小于最小炮的特征只能靠邻近炮的剂量拖尾「印出来」，或被 MRC 禁止。因此 fracturing 不是纯计算几何：它被电子光学硬件量化。台阶的空间频率若落在晶圆通带内，会经 MEF 变成晶圆 LER 的一截——通常掩模台阶远在通带外，但过碎的助条例外。</p>',14)),(r(),s(p,null,{default:e(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20POLY%5B%22%E6%8E%A9%E6%A8%A1%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20CUT%5B%22%E7%9F%A9%E5%BD%A2%20%2F%20%E4%B8%89%E8%A7%92%E5%88%86%E5%89%B2%22%5D%0A%20%20CUT%20--%3E%20SHOT%5B%22%E7%82%AE%E5%88%97%E8%A1%A8%20%2B%20%E5%89%82%E9%87%8F%22%5D%0A%20%20SHOT%20--%3E%20VSB%5B%22VSB%20%E5%86%99%E5%85%A5%22%5D%0A%20%20POLY%20--%3E%20MB%5B%22%E5%A4%9A%E6%9D%9F%3A%20%E6%94%B9%E6%A0%85%E6%A0%BC%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分割不提高分辨率。它只把几何投影到机台基。ILT 曲线在 VSB 上「能切」不等于「写得完」；产能论证必须报炮数，不能只报 clips 漂亮。不要把某 EDA 分割器的专有启发式写成物理定律。</p><p>后课默认：VSB 路径上几何已经是炮；MPC 在炮或多边形上补偿工艺，不是再切一次拓扑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VSB fracturing 把多边形收成矩形/三角炮；炮数驱动写入时间。</li><li>切法受最小炮、台阶误差与 PEC 假设约束，不是任意三角化。</li><li>多束路径用栅格化代替炮列表。</li><li>出处：VSB 写掩模与 fracturing 的公开工程论述；SPIE Photomask。</li></ul>',5))])}const P=o(h,[["render",u]]);export{g as __pageData,P as default};
